from collections import Counter

def fill_even_zero(grid, background):
    result = [list(row) for row in grid]
    for r, row in enumerate(result):
        nbg_positions = [c for c in range(len(row)) if row[c] != background]
        if not nbg_positions:
            continue
        for c in range(nbg_positions[0], nbg_positions[-1] + 1):
            if result[r][c] == background:
                result[r][c] = 2
        for c in range(len(row) - 1):
            if row[c] == 0 and c % 2 == 0:
                result[r][c + 1] = 2
    return result

